-- Individual lessons for reviewed videos 4–8. No class access is copied or opened.
BEGIN;
INSERT INTO public.lessons (id,title,slug,unit_id,unit,lesson_number,lesson_type,published,estimated_time,description,content_blocks)
SELECT '7456e6c4-fd01-455f-b0a2-e8e1a0f65304'::uuid,'Position & displacement in 2D and 3D','video-4-position-displacement-in-2d-and-3d','unit-1',(SELECT name FROM public.units WHERE id='unit-1'),103,'video',true,12,'How does final minus initial work when position has more than one coordinate?','{"schemaVersion":1,"presentation":"physics-path","dayType":"STANDARD","learningPath":{"version":1,"kind":"lesson","focus":"How does final minus initial work when position has more than one coordinate?","targetSlugs":["u1.vocab-position-distance-displacement"],"foundations":false},"blocks":[{"id":"video-djR8sAAi740","type":"instruction_video","youtubeId":"djR8sAAi740","title":"Position & displacement in 2D and 3D","summary":"A position has one coordinate per axis: (x, y) in a plane or (x, y, z) in space. Calculate displacement one component at a time, always final minus initial. Do not subtract an x-coordinate from a y-coordinate.","targetId":"u1.vocab-position-distance-displacement","workshop":{"stage":"Watch & understand","pageBreakBefore":true}},{"id":"scope-djR8sAAi740","type":"prose","markdown":"Extends position and displacement to two and three dimensions."},{"id":"check-djR8sAAi740","type":"question","capture":true,"targetId":"u1.vocab-position-distance-displacement","evidenceRole":"practice","sei":{"visual":{"src":"/learning/video-position.svg","alt":"Reference model for interpreting measurements, positions and direction."},"frames":[{"level":1,"text":"I notice ___. This means ___ because ___."},{"level":3,"text":"My reasoning is ___, supported by ___."}],"wordBank":["quantity","unit","position","change","direction","evidence"],"modes":["text","sketch"]},"workshop":{"stage":"Check your thinking","pageBreakBefore":true},"question":{"prompt":"An object moves from (1, −2) m to (4, 2) m. What is its displacement?","options":[{"id":"A","text":"(3, 4) m","feedback":"Subtract separately: 4 − 1 = 3 and 2 − (−2) = 4."},{"id":"B","text":"(5, 0) m","feedback":"This adds coordinates. Displacement subtracts the initial position from the final position."},{"id":"C","text":"(4, 2) m","feedback":"That is the final position; displacement is the change from the initial position."}],"correctOptionId":"A"}},{"id":"explain-djR8sAAi740","type":"exit_ticket","capture":true,"targetId":"u1.vocab-position-distance-displacement","evidenceRole":"exit","prompt":"An object moves from (−2, 4, 1) m to (3, 4, −1) m. Find its displacement and explain the meaning of the component that is zero.","sei":{"visual":{"src":"/learning/video-position.svg","alt":"Reference model for interpreting measurements, positions and direction."},"frames":[{"level":1,"text":"I notice ___. This means ___ because ___."},{"level":3,"text":"My reasoning is ___, supported by ___."}],"wordBank":["quantity","unit","position","change","direction","evidence"],"modes":["text","sketch"]},"workshop":{"stage":"Apply & explain","pageBreakBefore":true}}]}'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.lessons existing WHERE existing.content_blocks->>'presentation'='physics-path' AND existing.content_blocks->'blocks' @> '[{"type":"instruction_video","youtubeId":"djR8sAAi740"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id,title,slug,unit_id,unit,lesson_number,lesson_type,published,estimated_time,description,content_blocks)
SELECT 'df1acb44-9f62-45cf-9270-1f1a2d413505'::uuid,'How far vs. exactly where: scalars, vectors & position','video-5-how-far-vs-exactly-where-scalars-vectors-position','unit-1',(SELECT name FROM public.units WHERE id='unit-1'),104,'video',true,12,'Why does a distance alone fail to identify a location?','{"schemaVersion":1,"presentation":"physics-path","dayType":"STANDARD","learningPath":{"version":1,"kind":"lesson","focus":"Why does a distance alone fail to identify a location?","targetSlugs":["u1.vocab-position-distance-displacement"],"foundations":false},"blocks":[{"id":"video-FshpPgPAeWM","type":"instruction_video","youtubeId":"FshpPgPAeWM","title":"How far vs. exactly where: scalars, vectors & position","summary":"A distance from an origin leaves many possible locations. A position vector adds direction: its tail is at the reference point and its head is at the object. Components describe the same arrow. Its magnitude is a scalar, found in 2D using the Pythagorean theorem.","targetId":"u1.vocab-position-distance-displacement","workshop":{"stage":"Watch & understand","pageBreakBefore":true}},{"id":"scope-FshpPgPAeWM","type":"prose","markdown":"Scalar versus vector, position-vector anatomy, components, and magnitude."},{"id":"check-FshpPgPAeWM","type":"question","capture":true,"targetId":"u1.vocab-position-distance-displacement","evidenceRole":"practice","sei":{"visual":{"src":"/learning/video-position.svg","alt":"Reference model for interpreting measurements, positions and direction."},"frames":[{"level":1,"text":"I notice ___. This means ___ because ___."},{"level":3,"text":"My reasoning is ___, supported by ___."}],"wordBank":["quantity","unit","position","change","direction","evidence"],"modes":["text","sketch"]},"workshop":{"stage":"Check your thinking","pageBreakBefore":true},"question":{"prompt":"A position vector is (5, 12) m. Which statement is correct?","options":[{"id":"A","text":"Its magnitude is 13 m; the components also identify direction.","feedback":"The magnitude is √(5² + 12²) = 13 m; components carry more information than magnitude alone."},{"id":"B","text":"Its magnitude is 17 m.","feedback":"Adding component magnitudes gives 17, but the straight-line magnitude follows the Pythagorean theorem."},{"id":"C","text":"Knowing only 13 m locates the object uniquely.","feedback":"Many locations are 13 m from the origin. Direction is also needed."}],"correctOptionId":"A"}},{"id":"explain-FshpPgPAeWM","type":"exit_ticket","capture":true,"targetId":"u1.vocab-position-distance-displacement","evidenceRole":"exit","prompt":"Compare the information in “10 m from the origin” and “position (6, 8) m.” Explain why they can describe the same distance but do not provide the same location information.","sei":{"visual":{"src":"/learning/video-position.svg","alt":"Reference model for interpreting measurements, positions and direction."},"frames":[{"level":1,"text":"I notice ___. This means ___ because ___."},{"level":3,"text":"My reasoning is ___, supported by ___."}],"wordBank":["quantity","unit","position","change","direction","evidence"],"modes":["text","sketch"]},"workshop":{"stage":"Apply & explain","pageBreakBefore":true}}]}'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.lessons existing WHERE existing.content_blocks->>'presentation'='physics-path' AND existing.content_blocks->'blocks' @> '[{"type":"instruction_video","youtubeId":"FshpPgPAeWM"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id,title,slug,unit_id,unit,lesson_number,lesson_type,published,estimated_time,description,content_blocks)
SELECT 'c1f8c609-88ad-4d42-93ce-25ae2b0c8206'::uuid,'The sign is the direction: position vectors in 1D','video-6-the-sign-is-the-direction-position-vectors-in-1d','unit-1',(SELECT name FROM public.units WHERE id='unit-1'),105,'video',true,12,'What does the sign tell you—and what does it not tell you?','{"schemaVersion":1,"presentation":"physics-path","dayType":"STANDARD","learningPath":{"version":1,"kind":"lesson","focus":"What does the sign tell you—and what does it not tell you?","targetSlugs":["u1.vocab-position-distance-displacement"],"foundations":false},"blocks":[{"id":"video-maoz-9mGWyk","type":"instruction_video","youtubeId":"maoz-9mGWyk","title":"The sign is the direction: position vectors in 1D","summary":"In one dimension, a sign supplies direction along the chosen axis. A position x = −3 m has magnitude |x| = 3 m. A vertical coordinate can use y with up positive. A negative position is a location, not proof that an object is moving in the negative direction.","targetId":"u1.vocab-position-distance-displacement","workshop":{"stage":"Watch & understand","pageBreakBefore":true}},{"id":"scope-maoz-9mGWyk","type":"prose","markdown":"Signed horizontal and vertical coordinates; magnitude versus position."},{"id":"check-maoz-9mGWyk","type":"question","capture":true,"targetId":"u1.vocab-position-distance-displacement","evidenceRole":"practice","sei":{"visual":{"src":"/learning/video-position.svg","alt":"Reference model for interpreting measurements, positions and direction."},"frames":[{"level":1,"text":"I notice ___. This means ___ because ___."},{"level":3,"text":"My reasoning is ___, supported by ___."}],"wordBank":["quantity","unit","position","change","direction","evidence"],"modes":["text","sketch"]},"workshop":{"stage":"Check your thinking","pageBreakBefore":true},"question":{"prompt":"An object is at x = −3 m. What can you conclude from this position alone?","options":[{"id":"A","text":"It is 3 m from the origin on the negative side.","feedback":"The sign gives the side of the origin and the magnitude gives the distance from it."},{"id":"B","text":"It is moving left.","feedback":"You need how position changes over time to determine the direction of motion."},{"id":"C","text":"Its distance from the origin is −3 m.","feedback":"Distance is nonnegative. The position is negative; its magnitude is 3 m."}],"correctOptionId":"A"}},{"id":"explain-maoz-9mGWyk","type":"exit_ticket","capture":true,"targetId":"u1.vocab-position-distance-displacement","evidenceRole":"exit","prompt":"With up positive, a probe moves from y = +7 m to y = +2 m. Find its displacement, state the direction of its motion, and distinguish that direction from the sign of its final position.","sei":{"visual":{"src":"/learning/video-position.svg","alt":"Reference model for interpreting measurements, positions and direction."},"frames":[{"level":1,"text":"I notice ___. This means ___ because ___."},{"level":3,"text":"My reasoning is ___, supported by ___."}],"wordBank":["quantity","unit","position","change","direction","evidence"],"modes":["text","sketch"]},"workshop":{"stage":"Apply & explain","pageBreakBefore":true}}]}'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.lessons existing WHERE existing.content_blocks->>'presentation'='physics-path' AND existing.content_blocks->'blocks' @> '[{"type":"instruction_video","youtubeId":"maoz-9mGWyk"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id,title,slug,unit_id,unit,lesson_number,lesson_type,published,estimated_time,description,content_blocks)
SELECT '685abc3e-737c-4572-9be2-928f8fd7a707'::uuid,'Length, time & rates of change: why we divide by time','video-7-length-time-rates-of-change-why-we-divide-by-time','unit-1',(SELECT name FROM public.units WHERE id='unit-1'),106,'video',true,12,'What does “per second” mean in a motion measurement?','{"schemaVersion":1,"presentation":"physics-path","dayType":"STANDARD","learningPath":{"version":1,"kind":"lesson","focus":"What does “per second” mean in a motion measurement?","targetSlugs":["u1.kinematics-language","foundations.units-quantities"],"foundations":false},"blocks":[{"id":"video-YViTBR_aygk","type":"instruction_video","youtubeId":"YViTBR_aygk","title":"Length, time & rates of change: why we divide by time","summary":"A rate compares a change with the time interval over which it occurs. Change in position is final minus initial; divide by elapsed time to find the average rate of change of position. Its units are length per time, such as m/s. A negative rate describes change toward the negative direction.","targetId":"u1.kinematics-language","workshop":{"stage":"Watch & understand","pageBreakBefore":true}},{"id":"scope-YViTBR_aygk","type":"prose","markdown":"The position-change-over-time idea that defines average velocity.\n\nLength, time, physical quantities, and combined units."},{"id":"check-YViTBR_aygk","type":"question","capture":true,"targetId":"u1.kinematics-language","evidenceRole":"practice","sei":{"visual":{"src":"/learning/video-rates.svg","alt":"Reference model contrasting a trip, displacement, distance and elapsed time."},"frames":[{"level":1,"text":"I notice ___. This means ___ because ___."},{"level":3,"text":"My reasoning is ___, supported by ___."}],"wordBank":["quantity","unit","position","change","direction","evidence"],"modes":["text","sketch"]},"workshop":{"stage":"Check your thinking","pageBreakBefore":true},"question":{"prompt":"Position changes from 8 m to 2 m in 3 s. What is the average rate of change of position?","options":[{"id":"A","text":"−2 m/s","feedback":"(2 − 8) m ÷ 3 s = −2 m/s."},{"id":"B","text":"+2 m/s","feedback":"The position decreased, so the average rate is negative with this axis choice."},{"id":"C","text":"−6 m","feedback":"−6 m is the displacement. Divide by elapsed time to obtain a rate."}],"correctOptionId":"A"}},{"id":"explain-YViTBR_aygk","type":"exit_ticket","capture":true,"targetId":"u1.kinematics-language","evidenceRole":"exit","prompt":"A probe moves from x = 10 km at t = 2 s to x = 4 km at t = 5 s. Calculate its average velocity, showing both subtractions and the units. Explain its sign.","sei":{"visual":{"src":"/learning/video-rates.svg","alt":"Reference model contrasting a trip, displacement, distance and elapsed time."},"frames":[{"level":1,"text":"I notice ___. This means ___ because ___."},{"level":3,"text":"My reasoning is ___, supported by ___."}],"wordBank":["quantity","unit","position","change","direction","evidence"],"modes":["text","sketch"]},"workshop":{"stage":"Apply & explain","pageBreakBefore":true}}]}'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.lessons existing WHERE existing.content_blocks->>'presentation'='physics-path' AND existing.content_blocks->'blocks' @> '[{"type":"instruction_video","youtubeId":"YViTBR_aygk"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id,title,slug,unit_id,unit,lesson_number,lesson_type,published,estimated_time,description,content_blocks)
SELECT 'f2770d7c-8494-4808-9ba2-fb463bd47508'::uuid,'Velocity vs. speed: average and instantaneous','video-8-velocity-vs-speed-average-and-instantaneous','unit-1',(SELECT name FROM public.units WHERE id='unit-1'),107,'video',true,12,'Why can average velocity be zero while average speed is not?','{"schemaVersion":1,"presentation":"physics-path","dayType":"STANDARD","learningPath":{"version":1,"kind":"lesson","focus":"Why can average velocity be zero while average speed is not?","targetSlugs":["u1.kinematics-language","u1.vocab-position-distance-displacement"],"foundations":false},"blocks":[{"id":"video-hj8usnvYrRo","type":"instruction_video","youtubeId":"hj8usnvYrRo","title":"Velocity vs. speed: average and instantaneous","summary":"Average velocity uses displacement divided by elapsed time; average speed uses total distance divided by elapsed time. Instantaneous velocity is the slope of the tangent to a position–time graph, and instantaneous speed is its magnitude. For an out-and-back trip, average speed is not generally the magnitude of average velocity.","targetId":"u1.kinematics-language","workshop":{"stage":"Watch & understand","pageBreakBefore":true}},{"id":"scope-hj8usnvYrRo","type":"prose","markdown":"Velocity, speed, average and instantaneous values; this does not replace the full acceleration target.\n\nUses distance/displacement and scalar/vector distinctions in rates."},{"id":"check-hj8usnvYrRo","type":"question","capture":true,"targetId":"u1.kinematics-language","evidenceRole":"practice","sei":{"visual":{"src":"/learning/video-rates.svg","alt":"Reference model contrasting a trip, displacement, distance and elapsed time."},"frames":[{"level":1,"text":"I notice ___. This means ___ because ___."},{"level":3,"text":"My reasoning is ___, supported by ___."}],"wordBank":["quantity","unit","position","change","direction","evidence"],"modes":["text","sketch"]},"workshop":{"stage":"Check your thinking","pageBreakBefore":true},"question":{"prompt":"A cart travels 6 m out and 6 m back in 4 s. What are its average velocity and average speed?","options":[{"id":"A","text":"0 m/s and 3 m/s","feedback":"Displacement is zero; total distance is 12 m. Divide each by 4 s."},{"id":"B","text":"3 m/s and 3 m/s","feedback":"3 m/s uses distance, which gives average speed. Average velocity uses displacement."},{"id":"C","text":"0 m/s and 0 m/s","feedback":"Returning makes displacement zero but does not erase the distance traveled."}],"correctOptionId":"A"}},{"id":"explain-hj8usnvYrRo","type":"exit_ticket","capture":true,"targetId":"u1.kinematics-language","evidenceRole":"exit","prompt":"Explain how a secant and a tangent on a position–time graph represent different kinds of velocity. Then explain why neither should be confused with total distance traveled.","sei":{"visual":{"src":"/learning/video-rates.svg","alt":"Reference model contrasting a trip, displacement, distance and elapsed time."},"frames":[{"level":1,"text":"I notice ___. This means ___ because ___."},{"level":3,"text":"My reasoning is ___, supported by ___."}],"wordBank":["quantity","unit","position","change","direction","evidence"],"modes":["text","sketch"]},"workshop":{"stage":"Apply & explain","pageBreakBefore":true}}]}'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.lessons existing WHERE existing.content_blocks->>'presentation'='physics-path' AND existing.content_blocks->'blocks' @> '[{"type":"instruction_video","youtubeId":"hj8usnvYrRo"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;
